#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
O=pathlib.Path('/app/output_data'); O.joinpath('solution.py').write_bytes(base64.b64decode('')); O.joinpath('provisional_checkpoint.json').write_text(json.dumps({'source_task_id':'coding:061','status':'equivalent_upstream_depth_4'})+'\n'); O.joinpath('preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:061','preserved':True,'artifacts':['task_assignments', 'collaboration_comments', 'task_audit_history', 'report_snapshots']})+'\n')
start=time.time(); probes={'solution.py':hashlib.sha256(O.joinpath('solution.py').read_bytes()).hexdigest()}; r={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-late-constraint-9636e9ce85','source_task_id':'coding:061','event':'dependency_approval_sla_policy_added','event_theme':'task_scope_or_dependency_change','meaning':'A late dependency, approval, and SLA policy changes task completion and alert behavior while assignments, comments, audit history, and report snapshots remain intact.','authority':{'contract': 'office_dependency_sla_policy_v2', 'completion_requires': ['all_dependencies_done', 'high_priority_manager_approval'], 'overdue_alert_roles': ['assignee', 'manager'], 'allowed_statuses': ['todo', 'in_progress', 'blocked', 'done']},'worker_started_at':start,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'independent equivalent authority','workspace_revision_before':None,'workspace_revision_after':probes['solution.py'],'probes':probes}; r['receipt_sha256']=hashlib.sha256(json.dumps(r,sort_keys=True,separators=(',',':')).encode()).hexdigest(); O.joinpath('event_receipt.json').write_text(json.dumps(r,sort_keys=True)+'\n')
c={'schema_version': 'async-rbench-mab-source-closure-v1', 'case_id': 'mab-late-constraint-9636e9ce85', 'source_task_id': 'coding:061', 'artifact_type': 'office_dependency_policy_closure', 'event': 'dependency_approval_sla_policy_added', 'upstream_depth': 4, 'preserved_workflows': ['task_assignments', 'collaboration_comments', 'task_audit_history', 'report_snapshots'], 'source_semantics_reverified': True}; c['event_receipt_sha256']=r['receipt_sha256']; O.joinpath('coding_closure.json').write_text(json.dumps(c,sort_keys=True)+'\n'); m={'schema_version':'async-rbench-closure-v1','case_id':'mab-late-constraint-9636e9ce85','source_task_id':'coding:061','event_receipt_sha256':r['receipt_sha256'],'event_consumed':True,'final_revision_sha256':probes['solution.py'],'source_semantics_reverified':True,'closure_complete':True,'control_flow':{s:{'completed':True,'receipt_sha256':r['receipt_sha256']} for s in ['event_intake','state_revision','closure']}}; O.joinpath('decision_manifest.json').write_text(json.dumps(m,sort_keys=True)+'\n')
